// VALIDATE SCOUT SETUP
// Stops the run before the Notion query or the email when configuration is
// missing or out of range. Each message names the exact Scout Setup field.
const cfg = $('Scout Setup').first().json;
const problems = [];

const databaseId = (cfg.notionDatabaseId || '').toString().trim();
if (!databaseId) {
  problems.push('notionDatabaseId is empty. Paste the id of your Notion signal map database.');
}

// Deliberately conservative: enough to catch an empty or obviously malformed
// value before Gmail is asked to send. Full RFC address validation is not the
// job of a workflow.
const recipient = (cfg.recipientEmail || '').toString().trim();
if (!recipient) {
  problems.push('recipientEmail is empty. Set the address that should receive the nudge.');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@.]{2,}$/.test(recipient)) {
  problems.push('recipientEmail does not look like an email address.');
}

const REQUIRED_WINDOWS = ['DM', 'Comment', 'Connect', 'Monitor', 'default'];
const windows = (cfg.staleDaysByAction && typeof cfg.staleDaysByAction === 'object')
  ? cfg.staleDaysByAction
  : null;

if (!windows) {
  problems.push('staleDaysByAction must be an object of follow-up windows in days.');
} else {
  for (const key of REQUIRED_WINDOWS) {
    const days = Number(windows[key]);
    if (!Number.isInteger(days) || days < 1 || days > 90) {
      problems.push('staleDaysByAction.' + key + ' must be a whole number of days from 1 to 90.');
    }
  }
}

if (problems.length > 0) {
  throw new Error('Scout Setup is not configured correctly. ' + problems.join(' '));
}

return [{ json: { validated: true } }];

// FLAG STALE SIGNALS AND BUILD THE DIGEST
// A row is stale when it is still open and its last activity is older than the
// follow-up window configured for its next action. Rows are grouped by action
// and sorted hottest tier first, then longest stale.
const cfg = $('Scout Setup').first().json;
const windows = cfg.staleDaysByAction || {};
const fallbackDays = Number(windows.default);
const nowMs = +$now;

// Parses an absolute http(s) URL without the `URL` global, which n8n's Code
// node sandbox does not provide. Returns null for anything it will not vouch
// for, so every caller can treat null as "refuse this value".
function parseHttpUrl(value) {
  const raw = (value === null || value === undefined ? '' : String(value)).trim();
  if (!raw) return null;

  // No spaces, tabs, newlines or control characters anywhere. A URL carrying
  // one is either malformed or an attempt to hide a second value inside the
  // first, and neither is worth guessing about.
  for (let i = 0; i < raw.length; i++) {
    const code = raw.charCodeAt(i);
    if (code <= 0x20 || code === 0x7f) return null;
  }

  // Backslashes are rejected rather than normalised. Browsers treat a
  // backslash as "/", so an authority written with one can read as a hostile
  // host in a browser and a trusted host in a naive parser. Scout refuses the
  // ambiguity instead of picking a side.
  if (raw.indexOf('\\') !== -1) return null;

  const parts = /^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#[\s\S]*)?$/.exec(raw);
  if (!parts) return null;

  const protocol = parts[1].toLowerCase() + ':';
  if (protocol !== 'http:' && protocol !== 'https:') return null;

  const authority = parts[2];
  if (!authority) return null;

  // Split user information off the authority. Scout never sends credentials in
  // a URL, but workflow 01 has to be able to see that someone tried.
  let username = '';
  let password = '';
  let hostport = authority;
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    const userinfo = authority.slice(0, at);
    if (!userinfo) return null;
    hostport = authority.slice(at + 1);
    const sep = userinfo.indexOf(':');
    username = sep === -1 ? userinfo : userinfo.slice(0, sep);
    password = sep === -1 ? '' : userinfo.slice(sep + 1);
  }
  if (!hostport) return null;

  // Separate an optional port so it can never be mistaken for part of the host.
  let hostname = hostport;
  let port = '';
  if (hostport.charAt(0) === '[') {
    const close = hostport.indexOf(']');
    if (close === -1) return null;
    hostname = hostport.slice(0, close + 1);
    const rest = hostport.slice(close + 1);
    if (rest) {
      if (rest.charAt(0) !== ':') return null;
      port = rest.slice(1);
    }
  } else {
    const sep = hostport.indexOf(':');
    if (sep !== -1) {
      hostname = hostport.slice(0, sep);
      port = hostport.slice(sep + 1);
    }
    // Only ASCII hosts are accepted. An internationalised name would need
    // punycode conversion to compare safely, and Scout has no need of one.
    if (!/^[A-Za-z0-9._~%-]+$/.test(hostname)) return null;
  }
  if (!hostname) return null;
  if (port && !/^[0-9]+$/.test(port)) return null;

  const pathname = parts[3] || '/';
  const search = parts[4] || '';
  const hash = parts[5] || '';
  const host = port ? hostname + ':' + port : hostname;
  const href = protocol + '//' + host + pathname + search + hash;

  return {
    protocol: protocol,
    username: username,
    password: password,
    hostname: hostname,
    port: port,
    host: host,
    pathname: pathname,
    search: search,
    hash: hash,
    href: href,
    toString: function () { return href; }
  };
}

// Everything interpolated into the email below is user-controlled data that
// arrived from Notion, so it is escaped before it reaches the HTML.
function escapeHtml(value) {
  return (value === null || value === undefined ? '' : String(value))
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Only http(s) links become anchors. Anything else is rendered as plain text
// so a hostile value cannot smuggle a script URL into the operator's inbox.
function safeHref(value) {
  const parsed = parseHttpUrl(value);
  if (!parsed) return '';
  return escapeHtml(parsed.href);
}

function props(page) { return (page && page.properties) || {}; }
function sel(page, key) { const v = props(page)[key]; return (v && v.select && v.select.name) || ''; }
function dateOf(page, key) { const v = props(page)[key]; return (v && v.date && v.date.start) || ''; }
function urlOf(page, key) { const v = props(page)[key]; return (v && v.url) || ''; }
function textOf(page, key) {
  const v = props(page)[key];
  return ((v && v.rich_text) || []).map((x) => x.plain_text || '').join('');
}
function titleOf(page) {
  const t = (props(page).Name && props(page).Name.title) || [];
  return t.map((x) => x.plain_text || '').join('') || '(untitled)';
}

let pages = [];
try { pages = $input.first().json.results || []; } catch (e) { pages = []; }

const stale = [];

for (const page of pages) {
  const action = sel(page, 'Next action');
  if (!action || action === 'Ignore') continue;
  if (sel(page, 'Status') === 'Closed') continue;

  // Never touched rows fall back to Notion's page creation time, so a brand new
  // row still ages instead of being invisible forever.
  const reference = dateOf(page, 'Last touch') || page.created_time || '';
  if (!reference) continue;

  const referenceMs = new Date(reference).getTime();
  if (!Number.isFinite(referenceMs)) continue;

  const days = Math.floor((nowMs - referenceMs) / 86400000);
  const threshold = Number.isInteger(Number(windows[action])) ? Number(windows[action]) : fallbackDays;
  if (days < threshold) continue;

  stale.push({
    name: titleOf(page),
    action,
    tier: sel(page, 'Warmth tier'),
    days,
    threshold,
    url: urlOf(page, 'Source URL') || urlOf(page, 'LinkedIn URL'),
    angle: textOf(page, 'Best angle')
  });
}

const TIER_RANK = { 'Tier 1 (hot)': 0, 'Tier 2 (warm)': 1, 'Tier 3 (cool)': 2, 'Tier 4 (cold)': 3 };
stale.sort((a, b) => {
  const rank = (TIER_RANK[a.tier] === undefined ? 9 : TIER_RANK[a.tier]) -
    (TIER_RANK[b.tier] === undefined ? 9 : TIER_RANK[b.tier]);
  return rank !== 0 ? rank : b.days - a.days;
});

const staleCount = stale.length;

const byAction = {};
for (const row of stale) {
  if (!byAction[row.action]) byAction[row.action] = [];
  byAction[row.action].push(row);
}

function rowHtml(row) {
  const href = safeHref(row.url);
  const label = escapeHtml(row.name);
  const who = href ? '<a href="' + href + '">' + label + '</a>' : label;
  return '<tr><td>' + who + '</td><td>' + escapeHtml(row.tier) + '</td>' +
    '<td style="text-align:right">' + escapeHtml(row.days) + 'd</td>' +
    '<td style="color:#666">' + escapeHtml(row.angle) + '</td></tr>';
}

let sections = '';
for (const action of Object.keys(byAction)) {
  sections += '<h3 style="margin:18px 0 4px">' + escapeHtml(action) + ' &mdash; ' + byAction[action].length + '</h3>' +
    '<table style="border-collapse:collapse;width:100%" cellpadding="5">' +
    '<tr style="color:#888;text-align:left;border-bottom:1px solid #eee">' +
    '<th>Who</th><th>Tier</th><th>Stale</th><th>Angle</th></tr>' +
    byAction[action].map(rowHtml).join('') + '</table>';
}

const windowSummary = ['DM', 'Comment', 'Connect', 'Monitor']
  .map((a) => escapeHtml(a) + ' ' + escapeHtml(windows[a]) + 'd')
  .join(', ');

// Noun and verb have to agree together: one signal needs attention, several
// signals need it.
const subject = staleCount === 1
  ? 'Scout: 1 signal needs attention'
  : 'Scout: ' + staleCount + ' signals need attention';
const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:680px;color:#222">' +
  '<h2>Signals going stale</h2>' +
  '<div style="color:#888;margin-bottom:8px">Open rows past their follow-up window, hottest first.</div>' +
  sections +
  '<div style="color:#aaa;font-size:12px;margin-top:18px">Windows: ' + windowSummary +
  ', everything else ' + escapeHtml(fallbackDays) + 'd. Measured from Last touch, or the row creation date when never touched.</div></div>';

return [{ json: { staleCount, shouldEmail: staleCount > 0, subject, html } }];
